           <div class="actions">
             <button type="submit">Submit quiz</button>
             <p class="result" id="result" role="status" aria-live="polite"></p>
           </div>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#quiz-form");
       const result = document.querySelector("#result");

       const answers = {
         "question-1": ["python", "javascript"],
         "question-2": ["css", "html"],
         "question-3": ["r", "python", "fortran"]
       };

       function getSelectedValues(questionName) {
         return Array.from(form.querySelectorAll(`input[name="${questionName}"]:checked`))
           .map((input) => input.value)
           .sort();
       }

       function arraysMatch(first, second) {
         return first.length === second.length && first.every((value, index) => value === second[index]);
       }

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         let score = 0;
         const questionNames = Object.keys(answers);
         const unanswered = questionNames.filter((questionName) => getSelectedValues(questionName).length === 0);

         if (unanswered.length > 0) {
           result.dataset.tone = "error";
           result.textContent = "Please select at least one answer for every question.";
           return;
         }

         questionNames.forEach((questionName) => {
           const selected = getSelectedValues(questionName);
           const correct = [...answers[questionName]].sort();

           if (arraysMatch(selected, correct)) {
             score += 1;
           }
         });

         result.dataset.tone = score === questionNames.length ? "success" : "";
         result.textContent = `You scored ${score} out of ${questionNames.length}.`;
       });
     </script>
   </body>
